"""Static answer-key numbers, generated by the engine and frozen at build time (decision D6).

    python -m labcalc.answers > ../web/src/content/generated/answers.json

Every entry is {"v": full-precision string, "d": display string}. The answer *text* lives in the web
content files and references these numbers by key, e.g. ``{{exp4.q1.lambda}}``. Data-dependent
answers (Exp 5 Q6 table for the team's distances, Exp 6 Q3/Q6, Exp 7 Q6) are produced live by the
pipelines.
"""

from __future__ import annotations

import json
import sys

from mpmath import atan, degrees, log, mp, mpf, sin, sqrt, workdps

from . import WORK_DPS, __version__
from .constants import CS137, GRAPHITE_D, MATERIALS, get, graphite_C, material
from .experiments.exp5 import g_exact, x_approx
from .rounding import fmt_sig, full, round_report

ENGINE_VERSION = __version__


def N(x, sig=4, unit=""):
    d = fmt_sig(x, sig)
    return {"v": full(x, 25), "d": d + (f" {unit}" if unit else "")}


def NU(x, u, unit=""):
    return {"v": full(x, 25), "u": full(u, 25), "d": round_report(x, u).text(unit)}


def _exp3(k):
    R_q = mpf("1.09737e7")  # Q3 instructs this value
    out = {"hc_eVnm": N(k["hc_eVnm"], 9, "eV·nm"), "hc_Jm": N(k["h"] * k["c"], 6, "J·m")}
    # Q1 example
    out["q1_example_E"] = N(k["hc_eVnm"] / 500, 4, "eV")
    # Q2 Lyman / Paschen
    for nm, R in (("R", R_q), ("RH", k["RH"])):
        out[f"lyman_limit_{nm}"] = N(1 / R * mpf("1e9"), 5, "nm")
        out[f"lyman_alpha_{nm}"] = N(1 / (R * (1 - mpf(1) / 4)) * mpf("1e9"), 5, "nm")
        out[f"paschen_limit_{nm}"] = N(9 / R * mpf("1e9"), 4, "nm")
        out[f"paschen_alpha_{nm}"] = N(1 / (R * (mpf(1) / 9 - mpf(1) / 16)) * mpf("1e9"), 5, "nm")
    # Q3 table
    rows = []
    n_air = mpf("1.000277")  # standard air near 550 nm (approx.); Advanced only
    nist = {3: "656.279", 4: "486.135", 5: "434.0472", 6: "410.1734", 7: "397.0075"}
    colours = {3: "red", 4: "cyan (blue-green)", 5: "blue-violet", 6: "violet", 7: "deep violet (near UV, edge of visibility)"}
    for n in range(3, 8):
        lam = 1 / (R_q * (mpf(1) / 4 - mpf(1) / n ** 2)) * mpf("1e9")
        lam_H = 1 / (k["RH"] * (mpf(1) / 4 - mpf(1) / n ** 2)) * mpf("1e9")
        rows.append({"ni": n, "nf": 2, "lambda": N(lam, 5, ""), "lambda_RH": N(lam_H, 5), "lambda_RH_air": N(lam_H / n_air, 5),
                     "nist_air": nist[n], "colour": colours[n], "E_eV": N(k["hc_eVnm"] / lam, 4)})
    out["q3_table"] = rows
    # Theory check of eq. 3.7 (corrected exponent h³) and E1 = −13.6 eV (eq. 3.3 with h²)
    for nm, kk in (("codata", k), ("guide", get("guide"))):
        c = kk["c"] if nm == "codata" else mpf("2.99792458e8")
        R37 = kk["me"] * kk["e"] ** 4 / (8 * kk["eps0"] ** 2 * kk["h"] ** 3 * c)
        E1 = kk["me"] * kk["e"] ** 4 / (8 * kk["eps0"] ** 2 * kk["h"] ** 2) / kk["e"]
        out[f"eq37_{nm}"] = N(R37, 6, "m⁻¹")
        out[f"E1_{nm}"] = N(-E1, 4, "eV")
    out["RH_codata"] = N(k["RH"], 9, "m⁻¹")
    out["Rinf_codata"] = N(k["Rinf"], 11, "m⁻¹")
    out["RH_Rinf_diff_pct"] = N((k["Rinf"] / k["RH"] - 1) * 100, 3, "%")
    return out


def _exp4(k):
    out = {}
    h, me, e, c = k["h"], k["me"], k["e"], k["c"]
    # Q1 grain of sand
    m, v = mpf("3e-11"), mpf(340)
    p = m * v
    lam = h / p
    out["q1"] = {"m": N(m, 2, "kg"), "p": N(p, 3, "kg·m/s"), "lambda": N(lam, 3, "m"), "ratio_atom": N(lam / mpf("2.2e-10"), 2),
                 "ratio_d1": N(lam / mpf(GRAPHITE_D["d1"]), 2)}
    # Q2 electron at 2 kV
    U = mpf(2000)
    lnr = h / sqrt(2 * me * e * U)
    lr = h / sqrt(2 * me * e * U * (1 + e * U / (2 * me * c ** 2)))
    out["q2"] = {"lambda": N(lnr, 4, "m"), "lambda_pm": N(lnr * mpf("1e12"), 4, "pm"), "lambda_rel": N(lr, 4, "m"),
                 "rel_corr_pct": N((lr / lnr - 1) * 100, 2, "%"), "d1_over_lambda": N(mpf(GRAPHITE_D["d1"]) / lnr, 3),
                 "theta_deg": N(degrees(mp.asin(lnr / (2 * mpf(GRAPHITE_D["d1"])))), 3, "°"),
                 "v": N(sqrt(2 * e * U / me), 4, "m/s")}
    # Q3 table
    rows = []
    for i in range(5):
        U = mpf(3000) + 500 * i
        v_nr = sqrt(2 * e * U / me)
        gamma = 1 + e * U / (me * c ** 2)
        v_r = c * sqrt(1 - 1 / gamma ** 2)
        l_nr = h / (me * v_nr)
        l_r = h / sqrt(2 * me * e * U * (1 + e * U / (2 * me * c ** 2)))
        rows.append({"U_kV": fmt_sig(U / 1000, 2), "v_nr": N(v_nr, 4, ""), "v_r": N(v_r, 4), "beta_nr": N(v_nr / c, 4), "beta_r": N(v_r / c, 4),
                     "lambda_nr_pm": N(l_nr * mpf("1e12"), 4), "lambda_r_pm": N(l_r * mpf("1e12"), 4),
                     "dv_pct": N((v_nr / v_r - 1) * 100, 2), "dl_pct": N((l_nr / l_r - 1) * 100, 2), "gamma": N(gamma, 6)})
    out["q3_table"] = rows
    # Q5: D = 6 cm
    L, D = mpf("0.135"), mpf("0.06")
    t2 = D / (2 * L)
    two_theta = atan(t2)
    two_sin = 2 * sin(two_theta / 2)
    out["q5"] = {"tan2theta": N(t2, 4), "two_theta_deg": N(degrees(two_theta), 4, "°"), "sin2theta": N(sin(two_theta), 4),
                 "two_sin_theta": N(two_sin, 4), "err_pct": N((t2 / two_sin - 1) * 100, 2, "%"), "err_sin2_pct": N((t2 / sin(two_theta) - 1) * 100, 2, "%")}
    # constants
    C = graphite_C(k, L)
    kg = get("guide", "exp4")
    out["C_codata"] = N(C, 5, "m·V^½")
    out["C_guide_constants"] = N(graphite_C(kg, L), 4, "m·V^½")
    # expected ring sizes (sanity values)
    exp = []
    for U in ("2.5", "3", "3.5", "4", "4.5", "5"):
        Uv = mpf(U) * 1000
        exp.append({"U_kV": U, "D1_cm": N(C / mpf(GRAPHITE_D["d1"]) / sqrt(Uv) * 100, 3), "D2_cm": N(C / mpf(GRAPHITE_D["d2"]) / sqrt(Uv) * 100, 3)})
    out["expected_rings"] = exp
    out["graphite_a"] = N(2 * mpf(GRAPHITE_D["d2"]), 3, "m")
    out["d1_d2_ratio"] = N(mpf(GRAPHITE_D["d1"]) / mpf(GRAPHITE_D["d2"]), 4)
    return out


def _exp5(k):
    D = mpf("2.54")
    out = {}
    g3, g6 = g_exact(mpf(3), D), g_exact(mpf(6), D)
    out["q2"] = {"ratio_3_6": N(g3 / g6, 4), "g3": N(g3, 5), "g6": N(g6, 5), "far_ratio": N(mpf(4), 1)}
    tab = []
    for r in ("2", "3", "4", "5", "6", "8", "10", "12", "15", "20"):
        rr = mpf(r)
        tab.append({"r": r, "ratio": N(g_exact(rr, D) / g_exact(2 * rr, D), 4)})
    out["q2_table"] = tab
    out["q4"] = {"omega": "2π sr", "fraction": N(mpf(1) / 2, 1)}
    out["q5"] = {"Ci": N(mpf("3.7e10"), 2, "Bq")}
    tab = []
    for r in ("2", "3", "4", "5", "6", "8", "10", "15"):
        rr = mpf(r)
        u = D / rr
        tab.append({"r": r, "u": N(u, 4), "exact": N(g_exact(rr, D), 5), "approx": N(x_approx(rr, D), 5),
                    "err_pct": N((x_approx(rr, D) / g_exact(rr, D) - 1) * 100, 3), "series_pct": N(3 * u ** 2 / 16 * 100, 3)})
    out["q6_table"] = tab
    out["yield"] = {"I_gamma": N(mpf(CS137["I_gamma"]), 4), "inv": N(1 / mpf(CS137["I_gamma"]), 4)}
    out["params"] = {"eps": "0.2", "S": "1", "D": "2.54 cm"}
    return out


def _exp6(k):
    out = {"materials": []}
    for sym in ("Al", "Fe", "Pb"):
        m = material(sym)
        mu = m["mu"]
        out["materials"].append({"symbol": sym, "name": m["name"], "Z": m["Z"], "rho": N(m["rho"], 4, ""), "mu_rho": N(m["mu_rho"], 4),
                                 "mu": N(mu, 4), "x_e": N(1 / mu, 3), "hvl": N(log(2) / mu, 3), "x1000": N(log(1000) / mu, 3),
                                 "ZA": N(m["ZA"], 4), "photo_pct": N(m["photo"] / m["mu_rho"] * 100, 2), "compton_pct": N(m["compton"] / m["mu_rho"] * 100, 3)})
    out["ln1000"] = N(log(1000), 4)
    pb = material("Pb")
    out["q3_ref_x1000"] = N(log(1000) / pb["mu"], 3, "cm")
    mu, x = pb["mu"], mpf(3)
    out["q4"] = {"single": N(mp.e ** (-mu * x), 4), "split": N(mp.e ** (-mu * x / 3) * mp.e ** (-2 * mu * x / 3), 4)}
    out["q2"] = {"caliper_half": N(mpf("0.025"), 2, "mm"), "caliper_gum": N(mpf("0.05") / (2 * sqrt(3)), 2, "mm"),
                 "micrometer_half": N(mpf("0.005"), 1, "mm"), "micrometer_gum": N(mpf("0.01") / (2 * sqrt(3)), 2, "mm")}
    return out


def _exp7(k):
    out = {"eV": N(k["e"], 10, "J")}
    rows = []
    for U in ("10", "100", "1e8"):
        Uv = mpf(U)
        K = k["e"] * Uv
        v_cl = sqrt(2 * K / k["me"])
        gamma = 1 + K / (k["me"] * k["c"] ** 2)
        beta = sqrt(1 - 1 / gamma ** 2)
        rows.append({"U": U, "K_eV": N(Uv, 3, "eV"), "K_J": N(K, 4, "J"), "v_cl": N(v_cl, 4, "m/s"), "beta_cl": N(v_cl / k["c"], 4),
                     "gamma": N(gamma, 5), "beta": N(beta, 8), "v": N(beta * k["c"], 6, "m/s"), "rel_err_pct": N((v_cl / (beta * k["c"]) - 1) * 100, 3, "%")})
    out["q5_table"] = rows
    out["mec2"] = N(k["me"] * k["c"] ** 2 / k["e"] / mpf("1e6"), 8, "MeV")
    out["diff_405_578"] = N(k["hc_eVnm"] * (1 / mpf("404.7") - 1 / mpf("578.2")), 3, "V")
    out["diff_436_546"] = N(k["hc_eVnm"] * (1 / mpf("435.8") - 1 / mpf("546.1")), 3, "V")
    out["h_over_e"] = N(k["h"] / k["e"], 6, "V·s")
    lines = []
    for col, lam in (("UV", "365.4"), ("violet", "404.7"), ("blue", "435.8"), ("green", "546.1"), ("yellow", "578.2")):
        nu = k["c"] / (mpf(lam) * mpf("1e-9"))
        lines.append({"colour": col, "lambda": lam, "nu": N(nu, 5, "Hz"), "nu14": N(nu / mpf("1e14"), 4), "E_eV": N(k["hc_eVnm"] / mpf(lam), 4, "eV")})
    out["lines"] = lines
    return out


def generate() -> dict:
    with workdps(WORK_DPS):
        k = get("codata")
        return {"_meta": {"engine": ENGINE_VERSION, "dps": WORK_DPS, "constants": "CODATA 2022 / SI 2019"},
                "exp3": _exp3(k), "exp4": _exp4(k), "exp5": _exp5(k), "exp6": _exp6(k), "exp7": _exp7(k),
                "materials_ref": {s: {"Z": m["Z"], "rho": m["rho"], "mu_rho": m["mu_rho"]} for s, m in MATERIALS.items()}}


def dumps() -> str:
    return json.dumps(generate(), ensure_ascii=False, indent=1, sort_keys=True) + "\n"


if __name__ == "__main__":  # pragma: no cover
    sys.stdout.reconfigure(encoding="utf-8")
    sys.stdout.write(dumps())
